apacity(FULL); // Read full capacity (mAh)\n  unsigned int capacity = lipo.capacity(REMAIN); // Read remaining capacity (mAh)\n  int power = lipo.power(); // Read average power draw (mW)\n  int health = lipo.soh(); // Read state-of-health (%)\n\n  // Now print out those values:\n  String toPrint = String(soc) + "% | ";\n  toPrint += String(volts) + " mV | ";\n  toPrint += String(current) + " mA | ";\n  toPrint += String(capacity) + " / ";\n  toPrint += String(fullCapacity) + " mAh | ";\n  toPrint += String(power) + " mW | ";\n  toPrint += String(health) + "%";\n  \n  Serial.println(toPrint);\n\n  // LCD Graphics\n  tft.setTextColor(TFT_BLUE);\n  tft.drawRoundRect(10, 10, 300, 220, 10, TFT_BLUE);\n  tft.setTextColor(TFT_MAGENTA);\n  tft.drawString("State of Chage:", 20, 30);\n  tft.drawString("Battery Voltage:", 20, 55);\n  tft.drawString("Average Current:", 20, 80);\n  tft.drawString("Remain Capacity:", 20, 105);\n  tft.drawString("Full Capacity:", 20, 130);\n  tft.drawString("Average Power:", 20, 155);\n  tft.drawString("State of Health:", 20, 180);\n  \n  // Data\n  spr.createSprite(80, 170);\n  spr.fillSprite(TFT_BLACK);\n  spr.setFreeFont(FF17);\n  spr.setTextColor(TFT_WHITE);\n  spr.drawString(String(soc)+" % ", 0, 0);\n  spr.drawString(String(volts)+" mV ", 0, 25);\n  spr.drawString(String(current)+" mA ", 0, 50);\n  spr.drawString(String(capacity)+" mAh ", 0, 75);\n  spr.drawString(String(fullCapacity)+" mAh ", 0, 100);\n  spr.drawString(String(power)+" mW ", 0, 125);\n  spr.drawString(String(health)+" % ", 0, 150);\n  spr.pushSprite(170, 30);\n  spr.deleteSprite();\n}\n\nvoid setup()\n{\n  Serial.begin(115200);\n  tft.begin();\n  tft.setRotation(3);\n  tft.fillScreen(TFT_BLACK);\n  tft.setFreeFont(FF17); \n  setupBQ27441();\n  tft.setTextColor(TFT_GREEN);\n  tft.setCursor((320 - tft.textWidth("Battery Initialised!"))/2, 120);\n  tft.print("Battery Initialised!");\n  delay(1000);\n  tft.fillScreen(TFT_BLACK);\n}\n\nvoid loop() \n{\n  printBatteryStats();\n  delay(1000);\n}\n'})}),"\n",(0,a.jsx)(i.h2,{id:"visor-de-esquemas-en-l\xednea",children:(0,a.jsx)(i.strong,{children:"Visor de Esquemas en L\xednea"})}),"\n",(0,a.jsx)("div",{className:"altium-ecad-viewer","data-project-src":"https://http://files.seeedstudio.com/wiki/Wio-Terminal-Battery-Chassis/res/Wio%20Terminal%20Chassis%20-%20Battery_SCH_NEW.ZIP",style:{borderRadius:"0px 0px 4px 4px",height:500,borderStyle:"solid",borderWidth:1,borderColor:"rgb(241, 241, 241)",overflow:"hidden",maxWidth:1280,maxHeight:700,boxSizing:"border-box"}}),"\n",(0,a.jsx)(i.h2,{id:"recursos",children:(0,a.jsx)(i.strong,{children:"Recursos"})}),"\n",(0,a.jsxs)(i.ul,{children:["\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.strong,{children:"[ZIP]"})," ",(0,a.jsx)(i.a,{href:"https://files.seeedstudio.com/wiki/Wio-Terminal-Battery-Chassis/res/WioTerminal_battry_650mAh.rar",children:"Archivo de Dise\xf1o de Esquemas del Chasis de Bater\xeda Wio Terminal"})]}),"\n"]}),"\n",(0,a.jsx)(i.h2,{id:"soporte-t\xe9cnico",children:(0,a.jsx)(i.strong,{children:"Soporte T\xe9cnico"})}),"\n",(0,a.jsx)(i.p,{children:"\xa1Gracias por elegir nuestros productos! Estamos aqu\xed para brindarle diferentes tipos de soporte para asegurar que su experiencia con nuestros productos sea lo m\xe1s fluida posible. Ofrecemos varios canales de comunicaci\xf3n para satisfacer diferentes preferencias y necesidades."}),"\n",(0,a.jsxs)("div",{class:"button_tech_support_container",children:[(0,a.jsx)("a",{href:"https://forum.seeedstudio.com/",class:"button_forum"}),(0,a.jsx)("a",{href:"https://www.seeedstudio.com/contacts",class:"button_email"})]}),"\n",(0,a.jsxs)("div",{class:"button_tech_support_container",children:[(0,a.jsx)("a",{href:"https://discord.gg/eWkprNDMU7",class:"button_discord"}),(0,a.jsx)("a",{href:"https://github.com/Seeed-Studio/wiki-documents/discussions/69",class:"button_discussion"})]})]})}function h(e={}){let{wrapper:i}={...(0,n.R)(),...e.components};return i?(0,a.jsx)(i,{...e,children:(0,a.jsx)(c,{...e})}):c(e